// Rust guideline compliant 2026-02-21

use gpui_dataset_transformation::{cell_data_to_point_data, cell_data_to_point_data_validated};
#[cfg(feature = "candidate")]
use gpui_dataset_transformation::{CellToPointLimits, CellToPointPlan};
use gpui_mesh::{DataSet, Field, FieldData};
use gpui_profiler::AllocProbe;
use std::{hint::black_box, sync::Arc, time::Instant};

fn cpu_ns() -> u128 {
    let mut stamp = libc::timespec { tv_sec: 0, tv_nsec: 0 };
    // SAFETY: stamp is a valid writable C timespec. The synchronous clock call
    // retains no pointer; the status and resulting fields are checked below.
    let result = unsafe { libc::clock_gettime(libc::CLOCK_PROCESS_CPUTIME_ID, &mut stamp) };
    assert_eq!(result, 0);
    assert!(stamp.tv_sec >= 0 && (0..1_000_000_000).contains(&stamp.tv_nsec));
    stamp.tv_sec as u128 * 1_000_000_000 + stamp.tv_nsec as u128
}

fn data(n: usize, stretched: bool, mode: &str) -> DataSet {
    let mut data = DataSet::structured_grid("prepared", [n; 3], [0.0; 3], [1.0; 3]).unwrap();
    if stretched {
        for p in Arc::make_mut(&mut data.positions) { p[0] += (p[0] as usize % 3) as f64 * 0.125; }
    }
    let v = (0..data.cell_count()).map(|i| match mode {
        "positive" => ((i * 37) % 255 + 1) as f64 / 256.0,
        "mixed" => (((i * 37) % 511) as i32 - 255) as f64 / 256.0,
        _ => {
            let h = (i as u64).wrapping_mul(0x9e3779b97f4a7c15).rotate_left(17);
            let v = f64::from_bits((1023_u64 << 52) | (h & ((1_u64 << 52) - 1)));
            if h >> 63 == 0 { v } else { -v }
        }
    }).collect::<Vec<_>>();
    data.cell_data = vec![
        Field::scalar("s", v.clone()).on_cells(),
        Field::vector("v", v.iter().map(|&v| [v; 3]).collect::<Vec<_>>()).on_cells(),
        Field::tensor("t", v.iter().map(|&v| [v; 6]).collect::<Vec<_>>()).on_cells(),
        Field::complex("z", v.iter().map(|&v| [v; 2]).collect::<Vec<_>>()).on_cells(),
    ];
    data
}

fn bits(field: &Field) -> Vec<u64> {
    match &field.data {
        FieldData::Scalar(v) => v.iter().map(|v| v.to_bits()).collect(),
        FieldData::Vector(v) => v.iter().flatten().map(|v| v.to_bits()).collect(),
        FieldData::Tensor(v) => v.iter().flatten().map(|v| v.to_bits()).collect(),
        FieldData::Complex(v) => v.iter().flatten().map(|v| v.to_bits()).collect(),
    }
}

fn check(actual: &DataSet, expected: &DataSet) {
    actual.validate().unwrap();
    assert_eq!(actual.point_data.len(), expected.point_data.len());
    for (a, b) in actual.point_data.iter().zip(&expected.point_data) {
        assert_eq!(a.name, b.name); assert_eq!(a.valid, b.valid);
        assert_eq!(bits(a), bits(b));
    }
}

fn measure(key: &str, case: &str, retained: usize, count: usize, mut run: impl FnMut() -> DataSet, expected: &DataSet) {
    check(&run(), expected);
    let (mut times, mut cpus, mut calls, mut bytes) = (Vec::new(), Vec::new(), Vec::new(), Vec::new());
    for _ in 0..5 {
        let mut outputs = Vec::with_capacity(count);
        let mut probe = AllocProbe::new();
        let before = cpu_ns(); let start = Instant::now();
        for _ in 0..count { outputs.push(black_box(run())); }
        let elapsed = start.elapsed().as_nanos(); let cpu = cpu_ns() - before;
        let allocation = probe.sample("prepared");
        times.push(elapsed); cpus.push(cpu); calls.push(allocation.count); bytes.push(allocation.bytes);
        for out in &outputs { check(out, expected); }
        drop(outputs);
    }
    println!(r#"{{"key":"{key}","case":"{case}","count":{count},"retained_payload_bytes":{retained},"times_ns":{times:?},"cpu_times_ns":{cpus:?},"allocation_calls":{calls:?},"allocated_bytes":{bytes:?},"allocator_instrumentation":{}}}"#, cfg!(feature="allocations"));
}

fn batch(data: &DataSet) -> DataSet {
    let a = cell_data_to_point_data(data, "s", "scalar").unwrap();
    let b = cell_data_to_point_data(&a, "v", "vector").unwrap();
    cell_data_to_point_data(&b, "s", "alias").unwrap()
}

fn main() {
    for n in [8, 24] { for stretched in [false, true] { for mode in ["positive", "mixed", "full"] {
        let data = data(n, stretched, mode); let source = data.validated().unwrap();
        for name in ["s", "v", "t", "z"] {
            let key = format!("{n}/{stretched}/{mode}/{name}");
            let expected = cell_data_to_point_data_validated(source, name, "mean").unwrap();
            measure(&key, "legacy_cold", 0, 8, || cell_data_to_point_data_validated(source, name, "mean").unwrap(), &expected);
            #[cfg(feature = "candidate")] {
                let mut plan = CellToPointPlan::new(source).unwrap();
                let geometry = plan.geometry_payload_bytes();
                measure(&key, "prepared", geometry, 8, || plan.convert_field(name, "mean").unwrap(), &expected);
                measure(&key, "prepare_and_convert", 0, 8, || CellToPointPlan::new(source).unwrap().convert_field(name, "mean").unwrap(), &expected);
                let mut cached = CellToPointPlan::with_limits(source, CellToPointLimits { max_output_cache_bytes: 2 * 1024 * 1024, ..Default::default() }).unwrap();
                drop(cached.convert_field(name, "prime").unwrap());
                let retained = cached.geometry_payload_bytes() + cached.output_cache_payload_bytes();
                measure(&key, "cache_hit", retained, 64, || cached.convert_field(name, "mean").unwrap(), &expected);
            }
        }
        let key = format!("{n}/{stretched}/{mode}/batch"); let expected = batch(&data);
        measure(&key, "legacy_batch", 0, 4, || batch(&data), &expected);
        #[cfg(feature = "candidate")]
        measure(&key, "prepared_batch", 0, 4, || CellToPointPlan::new(data.validated().unwrap()).unwrap().convert_fields(&[("s", "scalar"), ("v", "vector"), ("s", "alias")]).unwrap(), &expected);
    } } }
}
